mapper.select:
SELECT o.id, o.order_no AS orderNo, o.user_id AS userId, u.username, o.total_amount AS totalAmount, o.status, o.receiver_name AS receiverName, o.receiver_phone AS receiverPhone, o.receiver_address AS receiverAddress, o.create_time AS createTime, o.payment_time AS paymentTime, o.delivery_time AS deliveryTime, o.receive_time AS receiveTime FROM orders o LEFT JOIN user u ON u.id = o.user_id AND u.deleted = 0 WHERE o.deleted = 0 AND o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.create_time DESC
